/**
 * Structural equality matching `fast-equals`' `deepEqual` semantics for the
 * subset of types this library cares about.
 *
 * Behavior summary:
 * - **Primitives**: SameValueZero via `a === b || (a !== a && b !== b)`. This
 *   makes `NaN` equal to `NaN` and `+0` equal to `-0`.
 * - **Functions / symbols**: reference equality (the `a === b` fast path).
 *   Registry symbols (`Symbol.for(x)`) already satisfy `===`.
 * - **Constructor mismatch**: unequal — a class instance is never structurally
 *   equal to a plain object with the same shape.
 * - **Arrays**: same length, every index recursively equal.
 * - **Plain objects** (constructor `Object` or null prototype): same own
 *   enumerable keys and values recursively equal. An explicit `undefined`
 *   value counts as a present key.
 * - **`Date`**: equal `getTime()` values. Two Invalid Dates (NaN time) are
 *   equal to each other (SameValueZero on the time).
 * - **`Map`**: same size; for each entry in `a`, find an unmatched entry in
 *   `b` whose key and value both deeply equal. Order-independent.
 * - **`Set`**: same size; for each element in `a`, find an unmatched element
 *   in `b` that deeply equals. Order-independent.
 * - **`RegExp`**: same `source` and `flags`.
 * - **Anything else with the same constructor** (typed arrays, class
 *   instances, `Promise`, errors, …): falls through to property comparison,
 *   matching fast-equals' conservative default — equal iff they have the same
 *   own enumerable keys with deeply equal values. Constructor mismatch above
 *   prevents cross-type false positives.
 *
 * No cycle detection. Form data is tree-shaped; a cyclic input would overflow
 * — surfacing the misuse instead of silently succeeding.
 */
export const deepEqual = (a: unknown, b: unknown): boolean => {
  // SameValueZero fast path: identical references, equal primitives, +0/-0,
  // NaN/NaN.
  if (a === b || (a !== a && b !== b)) {
    return true;
  }

  // Either side nullish (and not strictly equal above) ⇒ unequal.
  if (a === null || b === null) {
    return false;
  }

  const typeofA = typeof a;
  if (typeofA !== typeof b) {
    return false;
  }

  // Functions, symbols, and other primitive types only compare by reference.
  // (The `a === b` fast path already returned true for matching refs.)
  if (typeofA !== 'object') {
    return false;
  }

  // Class instances and plain objects must share a constructor to be equal.
  // This prevents e.g. a `URL` from comparing equal to a plain object that
  // happens to have the same own-key shape.
  if ((a as object).constructor !== (b as object).constructor) {
    return false;
  }

  if (Array.isArray(a)) {
    const bArr = b as unknown[];
    if (a.length !== bArr.length) {
      return false;
    }
    for (const [i, aItem] of a.entries()) {
      if (!deepEqual(aItem, bArr[i])) {
        return false;
      }
    }
    return true;
  }

  if (a instanceof Date) {
    const aTime = a.getTime();
    const bTime = (b as Date).getTime();
    return aTime === bTime || (aTime !== aTime && bTime !== bTime);
  }

  if (a instanceof Map) {
    const bMap = b as Map<unknown, unknown>;
    if (a.size !== bMap.size) {
      return false;
    }
    if (a.size === 0) {
      return true;
    }
    // Pairwise structural match. Map keys are themselves compared deeply
    // (matching fast-equals): two Maps with reference-distinct but
    // structurally-equal keys are still equal.
    const bEntries: [unknown, unknown][] = [...bMap];
    const matched: boolean[] = Array.from({ length: bEntries.length });
    outer: for (const [aKey, aValue] of a) {
      for (const [i, entry] of bEntries.entries()) {
        if (matched[i]) {
          continue;
        }
        if (deepEqual(aKey, entry[0]) && deepEqual(aValue, entry[1])) {
          matched[i] = true;
          continue outer;
        }
      }
      return false;
    }
    return true;
  }

  if (a instanceof Set) {
    const bSet = b as Set<unknown>;
    if (a.size !== bSet.size) {
      return false;
    }
    if (a.size === 0) {
      return true;
    }
    const bItems = [...bSet];
    const matched: boolean[] = Array.from({ length: bItems.length });
    outer: for (const aItem of a) {
      for (const [i, bItem] of bItems.entries()) {
        if (matched[i]) {
          continue;
        }
        if (deepEqual(aItem, bItem)) {
          matched[i] = true;
          continue outer;
        }
      }
      return false;
    }
    return true;
  }

  if (a instanceof RegExp) {
    const bRegExp = b as RegExp;
    return a.source === bRegExp.source && a.flags === bRegExp.flags;
  }

  // Fallback for plain objects, null-prototype objects, and any class
  // instance whose constructor matched: compare own enumerable string keys.
  const aObj = a as Record<string, unknown>;
  const bObj = b as Record<string, unknown>;
  const aKeys = Object.keys(aObj);
  if (aKeys.length !== Object.keys(bObj).length) {
    return false;
  }
  for (const key of aKeys) {
    if (!Object.prototype.hasOwnProperty.call(bObj, key) || !deepEqual(aObj[key], bObj[key])) {
      return false;
    }
  }
  return true;
};
